INSERT INTO "casos_tecnicos" ("id","fecha","titulo","projectId","cliente","equipos","etiquetas","sintoma","descartado","causa","solucion","leccion","updatedAt") VALUES
(gen_random_uuid()::text, DATE '2026-11-12',
 $$Smart meter con Warning 401 en red trifásica sin neutro$$,
 (SELECT "id" FROM "projects" WHERE "code" = 'PRY-2026-116'),
 $$Diego González (PRY-2026-116)$$,
 $$Inversor Growatt MID 15KTL3-XL2 (S/N USP3G6W002, importado por Growatt Brasil, 127/220 V), datalogger ShinePano ZOD5G5T013. Smart meter Eastron SDM630-Modbus V3 de conexión directa 100 A (S/N 250828512). Red trifásica de 230 V entre fases sin neutro. RS485 por UTP.$$,
 ARRAY['Growatt','MID 15KTL3-XL2','MID-XL2','Eastron','SDM630','smart meter','401','Meter abnormal','3P3','3P4','sin neutro','RS485','limitación de inyección'],
 $$✅ El inversor marcaba Warning 401 (Meter abnormal) mientras el medidor mostraba el símbolo de comunicación, que en general aparece cuando la conexión anda. ✅ Con el 401, el inversor (estado normal, 490 V en los paneles) entregaba entre 1 y 14 W. ⚠️ Se supone que era la limitación de inyección bajando la salida al no leer el medidor; la API decía que la limitación estaba apagada.$$,
 $$Cableado del medidor: B− con naranja y blanco-naranja, A+ con azul y blanco-azul (bien). En el conector de 16 pines del inversor, el naranja estaba en el pin 8 (bien); no se confirmó en qué pin estaba el azul. Velocidad, paridad y dirección no se llegaron a tocar.$$,
 $$✅ El medidor estaba en SYS = 3P4 (trifásico 4 hilos, como viene de fábrica) en una red de 3 hilos. ⚠️ Por qué eso corta la comunicación y no solo la medición no se sabe.$$,
 $$✅ Pasar el medidor a SYS = 3P3. El 401 desapareció y a las 15:23 el inversor generaba 1,9 kW sin alarmas.$$,
 $$En red sin neutro el SDM630 va en 3P3 sí o sí, y es lo primero que se revisa ante un 401: se pensó que esa configuración solo afectaba la medición y no la comunicación, y era eso. Pines del MID 15–25KTL3-XL2 (conector de señal de 16 pines): medidor en 7 (A) y 8 (B); 3-4 monitoreo, 5-6 batería; el conector de 4 pines del manual es solo de los modelos para Vietnam. En el SDM630 los bornes van B−, A+, G: el primero es el B. Menú del SDM630: mantener E unos 3 s, clave 1000; para Growatt 9600, sin paridad, 1 bit de parada. Pendiente aparte: se instaló un inversor de 15 kW y el proyecto dice 10 kW.$$,
 NOW()),
